const settings = {};
const items = $input.all();
items.forEach(item => {
  const key = item.json.setting_key;
  const value = item.json.setting_value;
  settings[key] = value;
});
return [{
  json: {
    admin_chat_id: settings.admin_chat_id,
    days_before_ideas: settings.days_before_ideas,
    supabase_url: settings.supabase_url,
    default_channel_name: settings.default_channel_name,
    publishing_channel_name: settings.publishing_channel_name,
    publishing_channel_chat_id: settings.publishing_channel_chat_id,
    publishing_channel_identifier: settings.publishing_channel_identifier
  }
}];

const nowMoscow = $now.setZone('Europe/Moscow');
const fiveMinutesAgo = nowMoscow.minus({ minutes: 5 });
const items = $input.all();
const seenIds = new Set();
const postsToPublish = items.filter(item => {
  const post = item.json;
  if (seenIds.has(post.id)) return false;
  let isReady = false;
  if (post.status === 'pending') {
    isReady = true;
  } else if (post.status === 'scheduled' && post.scheduled_at) {
    const scheduledMoscow = DateTime.fromISO(post.scheduled_at, { zone: 'utc' }).setZone('Europe/Moscow');
    isReady = scheduledMoscow <= nowMoscow && scheduledMoscow >= fiveMinutesAgo;
  }
  if (isReady) {
    seenIds.add(post.id);
    return true;
  }
  return false;
});
return postsToPublish;

const files = $input.all()
  .map(item => item.json)
  .filter(f => {
    const mt = (f.mimeType || '').toLowerCase();
    const name = (f.name || '').toLowerCase();
    return mt.startsWith('image/') || /\.(jpg|jpeg|png|webp)$/i.test(name);
  })
  .map(f => ({
    id: f.id,
    name: f.name,
    mimeType: f.mimeType,
    webViewLink: f.webViewLink || '',
    thumbnailLink: f.thumbnailLink || '',
    description: f.description || ''
  }));

if (!files.length) {
  throw new Error('В папке Google Drive не найдено изображений. Проверь доступ и ID папки.');
}

const title = $('Generate SEO Title').first().json.message?.content || '';
const post = $('Filter Ready Posts').first().json || {};

return [{
  json: {
    title,
    topic: post.topic || '',
    content_preview: String(post.content || '').slice(0, 1200),
    candidates: files.slice(0, 80),
    total_candidates: files.length
  }
}];

