const candidates = $('Prepare Candidate Image List').first().json.candidates || [];
const raw =
  $input.first().json.message?.content ||
  $input.first().json.text ||
  $input.first().json.output ||
  '';

let parsed = {};
try {
  const match = String(raw).match(/\{[\s\S]*\}/);
  parsed = match ? JSON.parse(match[0]) : {};
} catch (e) {
  parsed = {};
}

let selected = candidates.find(f => f.id === parsed.selected_id);

// fallback: если LLM вернула кривой JSON, выбираем детерминированно по ID поста,
// чтобы при разных постах фото не всегда было первым
if (!selected) {
  const postId = Number($('Filter Ready Posts').first().json.id || Date.now());
  selected = candidates[postId % candidates.length];
}

return [{
  json: {
    selected,
    selected_id: selected.id,
    selected_name: selected.name,
    selection_reason: parsed.reason || 'fallback selection',
    title: $('Generate SEO Title').first().json.message?.content || '',
    topic: $('Filter Ready Posts').first().json.topic || ''
  }
}];

const item = $input.first();

if (!item.binary || !item.binary.data) {
  throw new Error('Google Drive не вернул binary data. Проверь, что выбран именно файл-картинка и доступ к Drive работает.');
}

const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const mimeType = item.binary.data.mimeType || 'image/jpeg';
const base64 = buffer.toString('base64');

const title = $('Generate SEO Title').first().json.message?.content || '';
const post = $('Filter Ready Posts').first().json || {};
const topic = post.topic || title || 'бизнес и предпринимательство';
const selected = $('Normalize Selected Image').first().json.selected || {};
const reason = $('Normalize Selected Image').first().json.selection_reason || '';

const prompt = `Edit the provided real portrait photograph for a WordPress featured image about this headline: ${title}.

Use the uploaded photo as the main reference image.
Preserve the same woman, her face, age, hairstyle, facial proportions and recognizability.
Do not replace her with another person.
Do not change identity.
Do not make her look younger or older.
Do not distort the face, eyes, hands or body.

Create a professional business editorial visual for the topic of the article: ${topic}.
The image should look suitable for the Business Media Project project: expert, premium, warm, trustworthy, business-oriented.

Adapt the background and atmosphere to the article topic.
You may add subtle business-related context: office, documents, analytics, finance, taxes, entrepreneurship, consulting, neutral premium interior.
Do not add readable text, letters, numbers, logos, watermarks, captions, banners or UI elements.

Style:
- realistic photo
- professional lighting
- natural skin texture
- clean composition
- premium business look
- not cartoon
- not fantasy
- not overprocessed
- not obvious AI

Crop and adapt to square 1:1 format.
Final image must be publication-ready for WordPress and social media.`;

return [{
  json: {
    grok_prompt: prompt,
    input_image_data_url: `data:${mimeType};base64,${base64}`,
    selected_drive_file_id: selected.id || '',
    selected_drive_file_name: selected.name || '',
    selection_reason: reason,
    title,
    topic
  }
}];

