const data = $input.item.json;

if (data.error) {
  throw new Error('OpenRouter API error: ' + JSON.stringify(data.error));
}

// Основной формат OpenRouter image output:
// choices[0].message.images[0].image_url.url = data:image/...;base64,...
const imageUrl = data?.choices?.[0]?.message?.images?.[0]?.image_url?.url || '';

function makeBinaryFromBase64(raw) {
  let base64Data = String(raw || '');

  let mimeType = 'image/jpeg';
  const mimeMatch = base64Data.match(/^data:([^;]+);base64,/);
  if (mimeMatch) mimeType = mimeMatch[1];

  if (base64Data.includes(';base64,')) {
    base64Data = base64Data.split(';base64,')[1];
  } else if (base64Data.includes('base64,')) {
    base64Data = base64Data.split('base64,')[1];
  }

  base64Data = base64Data.replace(/[^A-Za-z0-9+/=]/g, '');

  if (!base64Data || base64Data.length < 1000) {
    throw new Error('Слишком короткий base64 изображения от Grok/OpenRouter');
  }

  const ext = mimeType.includes('png') ? 'png' : 'jpg';
  const uniqueName = 'grok_cover_' + Date.now() + '.' + ext;

  return this.helpers.prepareBinaryData(
    Buffer.from(base64Data, 'base64'),
    uniqueName,
    mimeType
  );
}

if (imageUrl && imageUrl.length > 1000) {
  const binaryData = await makeBinaryFromBase64.call(this, imageUrl);
  return {
    json: { success: true, source: 'choices.message.images', fileName: binaryData.fileName },
    binary: { data: binaryData }
  };
}

// Fallback: ищем длинную base64-строку во всём ответе
const allStrings = [];
function extractStrings(obj) {
  if (typeof obj === 'string') allStrings.push(obj);
  else if (Array.isArray(obj)) obj.forEach(extractStrings);
  else if (obj !== null && typeof obj === 'object') Object.values(obj).forEach(extractStrings);
}
extractStrings(data);
allStrings.sort((a, b) => b.length - a.length);

for (const str of allStrings) {
  if (str.length > 10000 && (str.includes('base64') || str.startsWith('/9j/') || str.startsWith('iVBOR'))) {
    const binaryData = await makeBinaryFromBase64.call(this, str);
    return {
      json: { success: true, source: 'fallback.long-string', fileName: binaryData.fileName },
      binary: { data: binaryData }
    };
  }
}

throw new Error('Grok/OpenRouter не вернул изображение. Проверь model, modalities и баланс OpenRouter.');
